import * as THREE from './vendor/three.module.js';
// Independent inspection stand: never included in project saves or scene export.
export class ModelPreview {
 constructor(loader,handlers){this.loader=loader;this.handlers=handlers;this.sequence=0;this.spin=true;this.areas=[];this.root=new THREE.Group();this.root.visible=false;this.canvas=document.createElement('canvas');this.canvas.width=1024;this.canvas.height=900;this.ctx=this.canvas.getContext('2d');this.texture=new THREE.CanvasTexture(this.canvas);this.texture.colorSpace=THREE.SRGBColorSpace;this.board=new THREE.Mesh(new THREE.PlaneGeometry(.72,.633),new THREE.MeshBasicMaterial({map:this.texture,side:THREE.DoubleSide}));this.root.add(this.board);this.stage=new THREE.Group();this.stage.position.y=-.55;this.root.add(this.stage);this.message='Wybierz model';this.draw();}
 disposeModel(root){if(!root)return;const textures=new Set();root.traverse(o=>{o.geometry?.dispose();for(const m of [o.material].flat().filter(Boolean)){if(m.map)textures.add(m.map);m.dispose();}});textures.forEach(t=>t.dispose());}
 clear(){for(const c of [...this.stage.children]){this.stage.remove(c);this.disposeModel(c);}this.stage.rotation.set(0,0,0);}
 install(model){this.clear();const box=new THREE.Box3().setFromObject(model),size=box.getSize(new THREE.Vector3()),centre=box.getCenter(new THREE.Vector3());model.position.sub(centre);const pivot=new THREE.Group();pivot.add(model);pivot.scale.setScalar(.37/Math.max(size.x,size.y,size.z,.001));model.traverse(o=>{if(!o.isMesh)return;const old=o.material;const flat=m=>new THREE.MeshBasicMaterial({map:m.map,color:m.color,side:THREE.DoubleSide,transparent:m.transparent,alphaTest:m.alphaTest,opacity:m.opacity});o.material=Array.isArray(old)?old.map(flat):flat(old);for(const m of [old].flat())m.dispose();});this.stage.add(pivot);}
 async load(page,part,path,label){const token=++this.sequence;this.clear();this.info={page,part,label};this.message='Wczytywanie modelu 3D…';this.sourceTexture?.dispose();this.sourceTexture=null;this.draw();try{const results=await Promise.allSettled([this.loader.loadAsync(path),new THREE.TextureLoader().loadAsync(`assets/images/${page.id}.jpg`)]);if(token!==this.sequence){if(results[0].status==='fulfilled')this.disposeModel(results[0].value.scene);if(results[1].status==='fulfilled')results[1].value.dispose();return;}if(results[1].status==='fulfilled')this.sourceTexture=results[1].value;if(results[0].status==='rejected')throw results[0].reason;this.install(results[0].value.scene);this.message=label;this.draw();}catch{if(token===this.sequence){this.message='Nie udało się wczytać podglądu. Wybierz ponownie.';this.draw();}}}
 showObject(piece,page,part,label){++this.sequence;const clone=piece.clone(true);clone.visible=true;clone.position.set(0,0,0);clone.quaternion.identity();clone.scale.setScalar(1);clone.traverse(o=>{if(o.geometry)o.geometry=o.geometry.clone();if(o.material){const copy=m=>{const n=m.clone();if(m.map)n.map=m.map.clone();return n;};o.material=Array.isArray(o.material)?o.material.map(copy):copy(o.material);}});this.install(clone);this.info={page,part,label,workspace:true};this.message=label;this.sourceTexture?.dispose();this.sourceTexture=null;const token=this.sequence;new THREE.TextureLoader().loadAsync(`assets/images/${page.id}.jpg`).then(t=>{if(token!==this.sequence){t.dispose();return;}this.sourceTexture=t;this.draw();}).catch(()=>{});this.draw();}
 draw(){const c=this.ctx;c.fillStyle='#101d28';c.fillRect(0,0,1024,900);c.fillStyle='#eaf4ff';c.font='bold 34px sans-serif';c.fillText('PODGLĄD MODELU',30,48);c.font='28px sans-serif';c.fillText(this.info?`f${this.info.page.label} · ${this.info.page.category}`:'Ładowanie katalogu…',30,92);const image=this.sourceTexture?.image;if(image?.width){const scaleFit=Math.min(560/image.width,420/image.height),h=image.height*scaleFit,w=image.width*scaleFit,x=30+(560-w)/2,y=115+(420-h)/2;c.drawImage(image,x,y,w,h);const b=this.info?.part?.bbox_norm;if(b){c.strokeStyle='#72e6ff';c.lineWidth=5;c.strokeRect(x+b[0]*w,y+b[1]*h,(b[2]-b[0])*w,(b[3]-b[1])*h);const sw=(b[2]-b[0])*image.width,sh=(b[3]-b[1])*image.height,scale=Math.min(330/sw,350/sh);c.drawImage(image,b[0]*image.width,b[1]*image.height,sw,sh,645,150,sw*scale,sh*scale);}}c.fillStyle='#bce5f7';c.font='26px sans-serif';c.fillText(this.message.slice(0,65),30,574);this.areas=[];const buttons=[['◀ Karta',this.handlers.prevCard],['Karta ▶',this.handlers.nextCard],['Kategoria',this.handlers.category],['◀ Fragment',this.handlers.prevPart],['Fragment ▶',this.handlers.nextPart],['Cały rysunek',this.handlers.allParts],['Obrót 180°',()=>this.stage.rotateY(Math.PI)],[this.spin?'Zatrzymaj obrót':'Obracaj model',()=>{this.spin=!this.spin;this.draw();}],[this.info?.workspace?'Duplikuj część':'Dodaj model',this.handlers.add]];buttons.forEach(([label,action],i)=>{const x=20+(i%3)*333,y=606+Math.floor(i/3)*90,w=317,h=76;c.fillStyle=i===8?'#a8d7ec':'#2a4658';c.fillRect(x,y,w,h);c.fillStyle=i===8?'#102432':'#fff';c.font='27px sans-serif';c.fillText(label,x+12,y+47);this.areas.push({x,y,w,h,action});});this.texture.needsUpdate=true;}
 pick(uv){const x=uv.x*1024,y=(1-uv.y)*900;return this.areas.find(a=>x>=a.x&&x<=a.x+a.w&&y>=a.y&&y<=a.y+a.h)?.action;}
 update(dt){if(this.root.visible&&this.spin)this.stage.rotation.y+=dt*.4;}
}
